import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BfWdyVj4.js";const u=JSON.parse('{"title":"Memory, history and the web","description":"","frontmatter":{},"headers":[],"relativePath":"features/memory.md","filePath":"features/memory.md","lastUpdated":1793092343000}'),s={name:"features/memory.md"};function n(i,e,h,d,l,m){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="memory-history-and-the-web" tabindex="-1">Memory, history and the web <a class="header-anchor" href="#memory-history-and-the-web" aria-label="Permalink to &quot;Memory, history and the web&quot;">​</a></h1><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p>The assistant remembers harmless things it&#39;s asked to (&quot;my favourite colour is green&quot;), never personal details, and nothing that changes its rules. In <a href="/guide/grown-ups#admin-mode-on-a-display">admin mode</a> grown-ups can also see, change and delete memories, and save house rules. The admin page&#39;s Memory tab shows the files.</p><ul><li><strong>The Claude Code brain</strong> keeps its memory as files in its own folder (<code>~/froghub-agent</code>).</li><li><strong>The API brain</strong> keeps it as one list in <code>~/.config/froghub/memory.md</code>. All of it goes into every prompt, and its <code>remember</code>, <code>change_memory</code> and <code>forget</code> tools keep it tidy, so &quot;forget that&quot; from the admin page really does. Past about 6,000 characters it&#39;s told to merge or forget old notes, and it&#39;s only shown the newest part.</li></ul><p>Off with the grown-ups&#39; &quot;Remember things between conversations&quot; switch.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>With the History switch on, the assistant can search what it was asked before: <code>search_history</code> takes words, a display and how many days back (&quot;what was that recipe yesterday?&quot;). It never sees what grown-ups asked in admin mode or from the admin page. See <a href="/guide/grown-ups#history">History</a>.</p><h2 id="web-search" tabindex="-1">Web search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web search&quot;">​</a></h2><ul><li><strong>Claude</strong> searches the web with Anthropic&#39;s own search tool.</li><li><strong>An OpenAI-compatible model</strong> (LM Studio, Ollama or OpenAI) gets a <code>web_search</code> tool that reads DuckDuckGo&#39;s results, or a <a href="https://docs.searxng.org" target="_blank" rel="noreferrer">SearXNG</a> instance&#39;s if <code>FROGHUB_SEARCH_URL</code> points at one (with <code>format=json</code> allowed).</li></ul><p>The local model has all the other tools too. For a small model that gets lost among them, <code>FROGHUB_FALLBACK_TOOLS=basic</code> offers it only reply, memory and web search.</p><p>Off with the grown-ups&#39; &quot;Look things up online&quot; switch.</p>',11)])])}const p=o(s,[["render",n]]);export{u as __pageData,p as default};
